def polish(text):
 parts=re.split(r'(`[^`\n]*`|https?://[^\s)]+|10[.]1021/[a-z0-9.]+|[0-9a-f]{40}|\bK[0-9]{2}\b|\bf(?:32|64)\b|\bfloat(?:32|64)\b|[Bb][15]|PH3|v2)',text)
 for i in range(0,len(parts),2):
  part=parts[i]
  for a,b in sorted(REPLACEMENTS.items(),key=lambda kv:-len(kv[0])):part=re.sub(r'(?<![A-Za-z])'+re.escape(a)+r'(?![A-Za-z])', lambda _: b, part)
  part=re.sub(r'(?<=[A-Za-z])(?=\d)', ' ',part)
  part=re.sub(r'(?<=\d)(?=[A-Za-zÅ])', ' ',part)
  part=re.sub(r'(?<=[,;])(?=[A-Za-z])', ' ',part)
  part=re.sub(r'(?<=[.])(?=[A-Z][a-z])', ' ',part)
  part=re.sub(r'(?<=[≤≥≈])(?=\d)', ' ',part)
  part=re.sub(r'(\d) e([−+-]?\d)',r'\1e\2',part)
  parts[i]=part
 return ''.join(parts).replace(';B5','; B5').replace(',B5',', B5').replace(',B1',', B1').replace('B5min','B5 min').replace('B1max','B1 max').replace('DOI10.','DOI 10.').replace('actualPH3','actual PH3').replace('v2API','v2 API')
